pat="Y_Y__Y_T_Y_Y"
opts={"A":"TYTYTY","B":"YTYTYT","C":"TTYYTT","D":"TYTYYT"}
def fill(o):
    it=iter(o); return "".join(next(it) if c=="_" else c for c in pat)
def periodic(s):
    return any(len(s)%p==0 and s==s[:p]*(len(s)//p) for p in range(2,len(s)//2+1))
fits=[k for k,v in opts.items() if periodic(fill(v))]
assert fits==["D"]

